def round_half_to_even(n):
    import math

    if n == int(n):
        return int(n)

    integer_part = int(n)
    fractional_part = n - integer_part

    if fractional_part > 0.5:
        return integer_part + 1
    elif fractional_part < 0.5:
        return integer_part
    else:
        # fractional_part == 0.5, round to even
        if integer_part % 2 == 0:
            return integer_part
        else:
            return integer_part + 1
