def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    # If not a tuple or empty, return as is
    if not cmd:
        return cmd

    cmd = list(cmd)
    exe = cmd[0]

    # If this is Windows, handle the shebang and path issues
    if os.name == "nt":
        # Check if the first argument is a script (not a .exe)
        # and has a shebang
        if not exe.lower().endswith(".exe"):
            # Find the interpreter
            interpreter = None
            args = []

            # Try to read the shebang
            if os.path.isfile(exe):
                try:
                    with open(exe, 'r', errors='replace') as f:
                        first_line = f.readline()
                    if first_line.startswith('#!'):
                        shebang = first_line[2:].strip()
                        parts = shebang.split()
                        if parts:
                            interpreter = parts[0]
                            args = parts[1:]
                except Exception:
                    pass

            # If we found an interpreter, use it
            if interpreter is not None:
                # The interpreter might have its own shebang (deep-path)
                # Check if the interpreter itself needs normalization
                interp_cmd = normalize_cmd((interpreter,) + tuple(args))
                return interp_cmd + (exe,) + tuple(cmd[1:])
            else:
                # If no shebang found, just use the script directly
                # but on windows, we may need to find an interpreter
                # For .py files, use 'python'
                if exe.lower().endswith('.py'):
                    return ('python',) + cmd
                # Otherwise, use the script as is
                return tuple(cmd)
        else:
            # It's an executable, no change needed
            return tuple(cmd)
    else:
        # Non-Windows: usually no adjustments needed
        return tuple(cmd)
