def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if key:
                k = key(args, kwargs)
            else:
                k = (args, tuple(sorted(kwargs.items())))
            if lock is not None:
                with lock:
                    if k in cache:
                        return cache[k]
            else:
                if k in cache:
                    return cache[k]
            result = func(*args, **kwargs)
            if lock is not None:
                with lock:
                    cache[k] = result
            else:
                cache[k] = result
            return result
        return wrapper
    return decorator
