def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        from libsbml import FillRequest, Source, getLibSBMLError
        from libsbml import isOfType
    except ImportError:
        return False

    # Check if it is a FillRequest element
    if isinstance(seq, FillRequest) or isOfType(seq, FillRequest):
        return True

    # Check if it contains at least one FillRequest
    if hasattr(seq, '__iter__'):
        try:
            for item in seq:
                if isinstance(item, FillRequest) or isOfType(item, FillRequest):
                    # Ensure it is not a Source sequence
                    if not (isinstance(seq, Source) or isOfType(seq, Source)):
                        return True
        except TypeError:
            pass

    # Ensure it is not a Source sequence
    if isinstance(seq, Source) or isOfType(seq, Source):
        return False

    return False
