    def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary.")

        # Constants for fixity types
        VALID_FIXITY_TYPES = {"checksum", "aead"}

        # Iterate over all fixity entries
        for file_path, fixity_element in fixity.items():
            if not isinstance(fixity_element, dict):
                raise ValueError(f"Fixity entry for file '{file_path}' must be a dictionary.")

            # Check for 'type' and 'value' keys
            if "type" not in fixity_element or "value" not in fixity_element:
                raise ValueError(f"Fixity entry for file '{file_path}' must include 'type' and 'value'.")

            fixity_type = fixity_element['type']
            fixity_value = fixity_element['value']

            # Validate fixity type
            if fixity_type not in VALID_FIXITY_TYPES:
                raise ValueError(f"Invalid fixity type '{fixity_type}' for file '{file_path}'.")

            # Validate value based on type
            if fixity_type == "checksum":
                if not isinstance(fixity_value, str) or len(fixity_value.strip()) == 0:
                    raise ValueError(f"Invalid checksum value for file '{file_path}'. Checksum must be a non-empty string.")
            elif fixity_type == "aead":
                # For AEAD, the value should be a base64 encoded string
                if not isinstance(fixity_value, str) or len(fixity_value.strip()) == 0:
                    raise ValueError(f"Invalid AEAD value for file '{file_path}'. AEAD value must be a non-empty string.")

            # Check that the file path is in the manifest
            if file_path not in manifest_files:
                raise ValueError(f"File '{file_path}' referenced in fixity block is not in the manifest.")
