def _group_files_by_xml_filename(source, xmls, files):
    grouped = {}
    for xml_name in xmls:
        precision_name = os.path.splitext(os.path.basename(xml_name))[0]
        grouped[precision_name] = Package(source=source, xml_file=xml_name, files=[])

    for file_path in files:
        if file_path in xmls:
            continue
        base_name = os.path.basename(file_path)
        # Check if the file matches any XML base name (ignoring extension)
        for precision_name, package in grouped.items():
            # A file belongs to a package if its basename (without extension) matches
            # the XML's basename (without extension), and it's not the XML itself
            if os.path.splitext(base_name)[0] == precision_name:
                package.files.append(file_path)
                break

    return grouped

