def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from sympy.logic.boolalg import And, Or, Not, BoolFunction

    a2 = []
    for a in args:
        for b in args:
            if a.is_Boolean is False or b.is_Boolean is False:
                continue
            if not isinstance(a, BoolFunction) or not isinstance(b, BoolFunction):
                continue
            if isinstance(a, And) and isinstance(b, Or):
                # Absorption: A & (A | B) = A
                if a.args[0] == b.args[0]:
                    expand_args = True
                    break
                for ia, ta in enumerate(a.args):
                    for ib, tb in enumerate(b.args):
                        if ia == ib:
                            continue
                        if ta == tb:
                            # Neither expression has overlapping variable,
                            # no expression with NOT, and there is overlap, set
                            # expand_args to True
                            expand_args = True
                            break
                        # negated expression with overlap
                        elif ta == Not(tb):
                            # A & (~A | B) = A & B
                            if all(t not in args for t in (ta, tb)):
                                expand_args = True
                                break
                            else:
                                # Check if one of the clauses in an And and one of the Or are negated
                                # and the And expression is a subset of the Or expression
                                ta_args = set(a.args)
                                tb_args = set(b.args)
                                if ta_args.issubset(tb_args) and Not(ta) in tb_args:
                                    expand_args = True
                                    break
                    if expand_args:
                        break
                if expand_args:
                    break
            elif isinstance(a, Or) and isinstance(b, And):
                # Absorption: A | (A & B) = A
                if a.args[0] == b.args[0]:
                    expand_args = True
                    break
                for ia, ta in enumerate(a.args):
                    for ib, tb in enumerate(b.args):
                        if ia == ib:
                            continue
                        if ta == tb:
                            # Neither expression has overlapping variable,
                            # no expression with NOT, and there is overlap, set
                            # expand_args to True
                            expand_args = True
                            break
                        # negated expression with overlap
                        elif ta == Not(tb):
                            # A | (~A & B) = A | B
                            if all(t not in args for t in (ta, tb)):
                                expand_args = True
                                break
                            else:
                                # Check if one of the clauses in an Or and one of the And are negated
                                # and the Or expression is a subset of the And expression
                                ta_args = set(a.args)
                                tb_args = set(b.args)
                                if ta_args.issubset(tb_args) and Not(ta) in tb_args:
                                    expand_args = True
                                    break
                    if expand_args:
                        break
            if expand_args:
                break
            else:
                a2.append(a)
    return a2
