def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces["error"]:
        return pieces["error"]

    style = pieces["style"]
    if style == "pep440":
        rendered = pieces["closest-tag"]
        if pieces["distance"]:
            rendered += ".post%d.dev%d" % (pieces["distance"], pieces["number"])
        if pieces["dirty"]:
            rendered += ".dirty"
    elif style == "pep440-legacy":
        rendered = pieces["closest-tag"]
        if pieces["distance"] or pieces["dirty"]:
            rendered += ".post0"
            if pieces["distance"]:
                rendered += ".dev%d" % pieces["distance"]
    elif style == "git-describe":
        rendered = pieces["closest-tag"]
        if pieces["distance"]:
            rendered += "-%d-g%s" % (pieces["distance"], pieces["short"])
        if pieces["dirty"]:
            rendered += "+dirty"
    elif style == "standard-version":
        rendered = pieces["closest-tag"]
        if pieces["distance"]:
            rendered += ".%d" % pieces["distance"]
        if pieces["dirty"]:
            rendered += "-dirty"
    else:
        raise ValueError("unknown style '%s'" % style)

    return rendered
