def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for version_dir in sorted(version_dirs, key=int):
        inventory_path = os.path.join(self.base_dir, version_dir, "inventory.json")
        if not os.path.exists(inventory_path):
            self._log.warning("Inventory not found for version %s", version_dir)
            continue

        try:
            with open(inventory_path, 'r', encoding='utf-8') as f:
                inventory = json.load(f)
        except (ValueError, IOError) as e:
            self._log.error("Failed to load inventory for version %s: %s", version_dir, e)
            continue

        # Process the inventory and record content digests different from root inventory
        class_name = self._class_name if hasattr(self, '_class_name') else None
        if class_name is None:
            if hasattr(self, 'capabilities'):
                class_name = self.capabilities.get('class_name')
            elif hasattr(self, 'config'):
                class_name = self.config.get('class_name')

        if class_name is None:
            self._log.warning("Could not determine class name for version %s", version_dir)
            continue

        for content_path, entry in inventory.get('contents', {}).items():
            if entry.get('class') != class_name:
                continue

            digest = entry.get('digest')
            root_digest = self.root_inventory.get('contents', {}).get(content_path, {}).get('digest')
            if digest and root_digest and digest != root_digest:
                self.content_digest_diffs.setdefault(content_path, set()).add(digest)

    return True
