def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    import re
    import yaml

    config_dict = {}
    error_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    data = yaml.safe_load(f)

            if not isinstance(data, dict):
                raise ValueError(f"Configuration file {filename} does not contain a valid dictionary")

            if overrides:
                def merge_configs(base, override):
                    result = base.copy()
                    for key, value in override.items():
                        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                            result[key] = merge_configs(result[key], value)
                        else:
                            result[key] = value
                    return result
                data = merge_configs(data, overrides)

            config_dict[filename] = data

        except Exception as e:
            error_records.append(logging.LogRecord(
                name="configuration",
                level=logging.ERROR,
                pathname="",
                lineno=0,
                msg=f"Error loading configuration file {filename}: {str(e)}",
                args=None,
                exc_info=None
            ))

    return config_dict, error_records
