def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append("[%s] provides: %s" % (iface, candidate))

    for name in iface.__names__:
        value = getattr(iface, name, None)
        if value is None:
            errors.append("[%s] attribute: %s" % (name, candidate))
        elif hasattr(value, '__call__'):
            # It's a method
            try:
                candidate_method = getattr(candidate, name, None)
                if candidate_method is None:
                    errors.append("[%s] method: %s" % (name, candidate))
                else:
                    if not callable(candidate_method):
                        errors.append("[%s] method not callable: %s" % (name, candidate))
            except AttributeError:
                errors.append("[%s] attribute: %s" % (name, candidate))
        else:
            # It's an attribute
            try:
                value = getattr(candidate, name, None)
            except AttributeError:
                errors.append("[%s] attribute: %s" % (name, candidate))

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("".join(errors))

    return True

