def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise TypeError("Expected at least one base class")

    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("Expected a metaclass, got {!r}".format(type(explicit_mc)))
        mc = explicit_mc
    else:
        mc = type
        for base in bases:
            if isinstance(base, type):
                base_mc = type(base)
            else:
                base_mc = type(base.__class__)
            if not issubclass(mc, base_mc):
                if issubclass(base_mc, mc):
                    mc = base_mc
                else:
                    raise TypeError("Inconsistent metaclasses: {!r} and {!r}".format(mc, base_mc))
    return mc
