def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    # Pattern to match existing HTML links
    link_pattern = re.compile(r'<a[^>]*href="([^"]*)"[^>]*>(.*?)</a>', re.DOTALL)

    def replace_existing_link(match):
        href = match.group(1)
        inner_text = match.group(2)
        # Check if it's a valid URL (starts with http or https)
        if href.startswith('http://') or href.startswith('https://'):
            # Add rel and target attributes if not present
            full_tag = match.group(0)
            if 'rel=' not in full_tag:
                full_tag = full_tag.replace('>', ' rel="noopener noreferrer">', 1)
            if 'target=' not in full_tag:
                full_tag = full_tag.replace('>', ' target="_blank">', 1)
            # If it doesn't have the attributes yet, we need to rebuild properly
            # Let's do a cleaner approach
            pass

        # Let's do it more carefully: extract the attributes and content
        # Actually, let's use a simpler approach
        if href.startswith('http://') or href.startswith('https://'):
            # Extract original attributes
            original_tag = match.group(0)
            # Ensure target and rel are present
            result = original_tag
            if 'target=' not in result:
                result = result.replace('<a ', '<a target="_blank" ', 1) if '<a ' in result else result.replace('<a', '<a target="_blank"', 1)
            if 'rel=' not in result:
                result = result.replace('<a ', '<a rel="noopener noreferrer" ', 1) if '<a ' in result else result.replace('<a', '<a rel="noopener noreferrer"', 1)
                if 'target=' in result and 'rel=' not in result:
                    # Already added target but not rel
                    pass
            return result
        else:
            return match.group(0)

    result = link_pattern.sub(replace_existing_link, text)

    # Now linkify plain text URLs
    url_pattern = re.compile(r'(?:https?://|www\.)[^\s<\]>]+(?:/[^\s<\]>]*|/[^\s<\]>]+)*[^\s<\]>]*', re.IGNORECASE)

    def linkify_url(match):
        url = match.group(0).strip()
        # Remove trailing punctuation that might have been captured
        while url and url[-1] in '.,;!?)]}&"\'':
            url = url[:-1]
        if not url:
            return match.group(0)

        # Add scheme if missing
        if not url.startswith('http://') and not url.startswith('https://'):
            if url.startswith('www.'):
                url = 'http://' + url
            else:
                url = 'http://' + url

        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    # We need to avoid replacing inside existing HTML tags
    # For simplicity, we'll do a basic replacement, but this is a known limitation
    # A more robust solution would parse HTML
    result = url_pattern.sub(linkify_url, result)

    return result
