import json
from xml.etree import ElementTree

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try JSON format first
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        pass

    # Try XRD format
    try:
        root = ElementTree.fromstring(document)
        # XRD namespace handling
        namespaces = {
            'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0',
            'atom': 'http://www.w3.org/2005/Atom'
        }

        result = {}

        # Get subject
        subject = root.find('xrd:subject', namespaces)
        if subject is not None:
            result['subject'] = subject.text

        # Get aliases
        aliases = []
        for alias in root.findall('xrd:alias', namespaces):
            aliases.append(alias.text)
        if aliases:
            result['aliases'] = aliases

        # Get links
        links = []
        for link in root.findall('xrd:link', namespaces):
            link_data = {}
            rel = link.get('rel')
            if rel:
                link_data['rel'] = rel
            href = link.get('href')
            if href:
                link_data['href'] = href
            template = link.get('template')
            if template:
                link_data['template'] = template
            type_ = link.get('type')
            if type_:
                link_data['type'] = type_
            links.append(link_data)
        if links:
            result['links'] = links

        return result

    except ElementTree.ParseError:
        raise ValueError("Unable to parse webfinger document in either JSON or XRD format")
