    def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        if "include" in parser_dict:
            include_list = parser_dict["include"]
            if isinstance(include_list, str):
                include_list = [include_list]
            for include_path in include_list:
                with open(include_path) as f:
                    include_dict = yaml.safe_load(f)
                self._include_groups(include_dict)
                for key in include_dict:
                    if key in parser_dict:
                        if isinstance(parser_dict[key], dict) and isinstance(include_dict[key], dict):
                            for sub_key, sub_value in include_dict[key].items():
                                if sub_key in parser_dict[key]:
                                    if isinstance(parser_dict[key][sub_key], list) and isinstance(include_dict[key][sub_key], list):
                                        parser_dict[key][sub_key].extend(include_dict[key][sub_key])
                                    else:
                                        parser_dict[key][sub_key] = include_dict[key][sub_key]
                                else:
                                    parser_dict[key][sub_key] = sub_value
                        else:
                            parser_dict[key] = include_dict[key]
                    else:
                        parser_dict[key] = include_dict[key]
            del parser_dict["include"]
