def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    import os

    spec_file = os.path.join(plugin_dir, 'plugin.json')

    if not os.path.exists(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found at {spec_file}")

    with open(spec_file, 'r') as f:
        spec = json.load(f)

    flat_dict = {}

    def flatten(d, parent_key=''):
        for k, v in d.items():
            new_key = f"{parent_key}{k}" if not parent_key else f"{parent_key}_{k}"
            if isinstance(v, dict):
                flatten(v, new_key)
            elif isinstance(v, list):
                if all(isinstance(item, (dict, list)) for item in v):
                    for i, item in enumerate(v):
                        if isinstance(item, dict):
                            flatten(item, f"{new_key}_{i}")
                        else:
                            flat_dict[new_key] = v
                else:
                    flat_dict[new_key] = v
            else:
                flat_dict[new_key] = v

    flatten(spec)
    return flat_dict
